create or replace function finance_private.current_period_reopen_worker_is_trusted() returns boolean language sql stable security definer set search_path='' as $$select false$$;create or replace function finance_private.current_actor_can_request_period_reopen(p_actor_id uuid,p_period_id uuid) returns boolean language sql stable security definer set search_path='' as $$select false$$;create or replace function finance_private.current_actor_can_approve_period_reopen(p_actor_id uuid,p_request_id uuid) returns boolean language sql stable security definer set search_path='' as $$select false$$;
revoke all on function finance_private.current_period_reopen_worker_is_trusted() from public,anon,authenticated;revoke all on function finance_private.current_actor_can_request_period_reopen(uuid,uuid) from public,anon,authenticated;revoke all on function finance_private.current_actor_can_approve_period_reopen(uuid,uuid) from public,anon,authenticated;
create or replace function finance_api.authorize_period_reopen_request(p_period_id uuid,p_permission text) returns jsonb language sql stable security definer set search_path='' as $$select case when p_permission='finance.periods.reopen.request' and auth.uid() is not null and finance_private.current_actor_can_request_period_reopen(auth.uid(),fp.id) then pg_catalog.jsonb_build_object('allowed',true,'legalEntityId',fp.legal_entity_id,'dealerAccountId',fp.dealer_account_id,'branchId',fp.branch_id,'parentPeriodId',fp.parent_period_id) else pg_catalog.jsonb_build_object('allowed',false) end from finance.finance_periods fp where fp.id=p_period_id and fp.scope_type='BRANCH'$$;
create or replace function finance_api.authorize_period_reopen_approval(p_request_id uuid,p_permission text) returns jsonb language sql stable security definer set search_path='' as $$select case when p_permission='finance.periods.reopen.approve' and auth.uid() is not null and finance_private.current_actor_can_approve_period_reopen(auth.uid(),ar.id) then pg_catalog.jsonb_build_object('allowed',true,'legalEntityId',fp.legal_entity_id,'dealerAccountId',fp.dealer_account_id,'branchId',fp.branch_id,'parentPeriodId',fp.parent_period_id) else pg_catalog.jsonb_build_object('allowed',false) end from finance.approval_requests ar join finance.finance_periods fp on fp.id=ar.subject_id and fp.scope_type='BRANCH' where ar.id=p_request_id and ar.subject_type='FINANCE_PERIOD_REOPEN'$$;
create or replace function finance_api.commit_period_reopen_request(p_actor_id uuid,p_period_id uuid,p_legal_entity_id uuid,p_dealer_account_id uuid,p_branch_id uuid,p_reason_code text,p_scope_description text,p_document_ids uuid[],p_expected_period_version bigint,p_idempotency_key text,p_intent_hash text,p_correlation_id uuid) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare p finance.finance_periods%rowtype;r uuid;v_snapshot jsonb;v_hash text;v_version bigint;v_existing jsonb;v_existing_hash text;v_payload jsonb;v_payload_hash text;v_previous text;v_audit text;
begin if not finance_private.current_period_reopen_worker_is_trusted() then raise exception using errcode='42501',message='period reopen worker denied';end if;if p_actor_id is null or p_period_id is null or p_legal_entity_id is null or p_dealer_account_id is null or p_branch_id is null or coalesce(pg_catalog.btrim(p_reason_code),'')='' or pg_catalog.length(p_reason_code)>100 or coalesce(pg_catalog.btrim(p_scope_description),'')='' or pg_catalog.length(p_scope_description)>2000 or pg_catalog.cardinality(p_document_ids)<1 or p_expected_period_version<1 or coalesce(pg_catalog.btrim(p_idempotency_key),'')='' or p_intent_hash!~'^[a-fA-F0-9]{64}$' or p_correlation_id is null then raise exception using errcode='22023',message='required reopen request fields missing';end if;perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('period-reopen:'||p_period_id::text,0));select om.payload,om.payload->>'intentHash' into v_existing,v_existing_hash from finance.outbox_messages om where om.aggregate_id=p_period_id and om.event_type='FINANCE_PERIOD_REOPEN_REQUESTED' and om.payload->>'idempotencyKey'=p_idempotency_key order by om.created_at_utc desc limit 1;if found then if v_existing_hash=p_intent_hash then return pg_catalog.jsonb_build_object('outcome','REPLAY','requestId',v_existing->>'requestId','periodId',p_period_id,'status','PENDING','version',1);end if;return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 select * into p from finance.finance_periods where id=p_period_id for update;if not found then raise exception using errcode='P0002',message='finance period not found';end if;if p.scope_type<>'BRANCH' or p.parent_period_id is null or p.legal_entity_id<>p_legal_entity_id or p.dealer_account_id<>p_dealer_account_id or p.branch_id<>p_branch_id then raise exception using errcode='42501',message='branch finance period scope mismatch';end if;if p.version<>p_expected_period_version or p.status<>'LOCKED' then return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;if exists(select 1 from pg_catalog.unnest(p_document_ids) x left join finance.document_references d on d.external_document_id=x and d.legal_entity_id=p.legal_entity_id and d.status='ACTIVE' where d.id is null) then raise exception using errcode='23514',message='active reopen evidence required';end if;
 v_snapshot:=pg_catalog.jsonb_build_object('periodId',p.id,'parentPeriodId',p.parent_period_id,'dealerAccountId',p.dealer_account_id,'branchId',p.branch_id,'periodVersion',p.version,'sourceSnapshotHash',p.source_snapshot_hash,'checkSnapshotHash',p.check_snapshot_hash,'lockedAtUtc',p.locked_at_utc,'reasonCode',p_reason_code,'scopeDescription',p_scope_description,'documentIds',(select pg_catalog.jsonb_agg(x order by x) from pg_catalog.unnest(p_document_ids)x));v_hash:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(v_snapshot::text,'UTF8'),'sha256'),'hex');insert into finance.approval_requests(legal_entity_id,subject_type,subject_id,approval_policy_version,prepared_by,subject_snapshot,subject_snapshot_hash,status,created_by,correlation_id) values(p.legal_entity_id,'FINANCE_PERIOD_REOPEN',p.id,'period-reopen-v1:'||p.version,p_actor_id,v_snapshot,v_hash,'PENDING',p_actor_id,p_correlation_id) returning id into r;insert into finance.approval_steps(approval_request_id,step_no,required_role,created_by,correlation_id) values(r,1,'finance-period-reopen-approver',p_actor_id,p_correlation_id);insert into finance.document_links(legal_entity_id,document_reference_id,subject_type,subject_id,purpose_code,created_by,correlation_id) select p.legal_entity_id,d.id,'FINANCE_PERIOD_REOPEN',r,'REOPEN_EVIDENCE',p_actor_id,p_correlation_id from finance.document_references d where d.external_document_id=any(p_document_ids) and d.legal_entity_id=p.legal_entity_id and d.status='ACTIVE';update finance.finance_periods set status='REOPEN_PENDING',version=version+1,correlation_id=p_correlation_id where id=p.id returning version into v_version;
 v_payload:=pg_catalog.jsonb_build_object('requestId',r,'periodId',p.id,'status','PENDING','version',1,'periodVersion',v_version,'snapshotHash',v_hash,'idempotencyKey',p_idempotency_key,'intentHash',p_intent_hash);v_payload_hash:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(v_payload::text,'UTF8'),'sha256'),'hex');insert into finance.outbox_messages(legal_entity_id,topic,event_type,aggregate_type,aggregate_id,aggregate_version,payload,payload_hash,status,correlation_id) values(p.legal_entity_id,'finance.period','FINANCE_PERIOD_REOPEN_REQUESTED','finance_period',p.id,v_version,v_payload,v_payload_hash,'PENDING',p_correlation_id);perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('audit:'||p.legal_entity_id::text,0));select ae.integrity_hash into v_previous from finance.audit_events ae where ae.legal_entity_id=p.legal_entity_id order by ae.created_at_utc desc,ae.id desc limit 1;v_audit:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(coalesce(v_previous,'GENESIS')||':'||r::text||':FINANCE_PERIOD_REOPEN_REQUESTED:'||v_hash||':'||p_correlation_id::text,'UTF8'),'sha256'),'hex');insert into finance.audit_events(legal_entity_id,actor_id,actor_type,action_code,subject_type,subject_id,decision,after_hash,previous_integrity_hash,integrity_hash,safe_context,correlation_id) values(p.legal_entity_id,p_actor_id,'USER','FINANCE_PERIOD_REOPEN_REQUESTED','approval_request',r,'ALLOW',v_hash,v_previous,v_audit,pg_catalog.jsonb_build_object('periodId',p.id,'periodVersion',v_version),p_correlation_id);return pg_catalog.jsonb_build_object('outcome','CREATED','requestId',r,'periodId',p.id,'status','PENDING','version',1);end$$;
create or replace function finance_api.commit_period_reopen_approval(p_actor_id uuid,p_request_id uuid,p_legal_entity_id uuid,p_dealer_account_id uuid,p_branch_id uuid,p_reason_code text,p_note_hash text,p_expected_version bigint,p_idempotency_key text,p_intent_hash text,p_correlation_id uuid) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare a finance.approval_requests%rowtype;p finance.finance_periods%rowtype;s jsonb;v_version bigint;v_payload jsonb;v_payload_hash text;v_previous text;v_audit text;v_existing jsonb;
begin if not finance_private.current_period_reopen_worker_is_trusted() then raise exception using errcode='42501',message='period reopen worker denied';end if;if p_actor_id is null or p_request_id is null or p_legal_entity_id is null or p_dealer_account_id is null or p_branch_id is null or coalesce(pg_catalog.btrim(p_reason_code),'')='' or pg_catalog.length(p_reason_code)>100 or (p_note_hash is not null and p_note_hash!~'^[a-fA-F0-9]{64}$') or p_expected_version<1 or coalesce(pg_catalog.btrim(p_idempotency_key),'')='' or p_intent_hash!~'^[a-fA-F0-9]{64}$' or p_correlation_id is null then raise exception using errcode='22023',message='required reopen approval fields missing';end if;perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('period-reopen-request:'||p_request_id::text,0));select * into a from finance.approval_requests where id=p_request_id for update;if not found then raise exception using errcode='P0002',message='reopen request not found';end if;s:=a.subject_snapshot;select * into p from finance.finance_periods where id=a.subject_id for update;if a.status='APPROVED' then select om.payload into v_existing from finance.outbox_messages om where om.event_type='FINANCE_PERIOD_REOPENED' and om.payload->>'requestId'=a.id::text order by om.created_at_utc desc limit 1;if found and v_existing->>'idempotencyKey'=p_idempotency_key and v_existing->>'intentHash'=p_intent_hash then return v_existing||pg_catalog.jsonb_build_object('outcome','REPLAY','periodStart',p.period_start,'periodEnd',p.period_end);end if;return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;if a.subject_type<>'FINANCE_PERIOD_REOPEN' or a.status<>'PENDING' or a.version<>p_expected_version or a.prepared_by=p_actor_id then return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;if p.scope_type<>'BRANCH' or p.legal_entity_id<>p_legal_entity_id or p.dealer_account_id<>p_dealer_account_id or p.branch_id<>p_branch_id or p.status<>'REOPEN_PENDING' or p.version<>(s->>'periodVersion')::bigint+1 or p.source_snapshot_hash is distinct from s->>'sourceSnapshotHash' or p.check_snapshot_hash is distinct from s->>'checkSnapshotHash' then return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 update finance.approval_steps set decision='APPROVE',decided_by=p_actor_id,decided_at_utc=pg_catalog.now(),evidence_ref=coalesce(p_note_hash,p_reason_code),correlation_id=p_correlation_id where approval_request_id=a.id and step_no=1 and decision is null;if not found then return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;update finance.approval_requests set status='APPROVED',version=version+1,correlation_id=p_correlation_id where id=a.id and version=p_expected_version;update finance.finance_periods set status='REOPENED',reopened_at_utc=pg_catalog.now(),reopened_by=p_actor_id,reopen_reason_code=p_reason_code,version=version+1,correlation_id=p_correlation_id where id=p.id returning version into v_version;
 v_payload:=pg_catalog.jsonb_build_object('requestId',a.id,'periodId',p.id,'parentPeriodId',p.parent_period_id,'dealerAccountId',p.dealer_account_id,'branchId',p.branch_id,'currencyCode',p.currency_code,'status','REOPENED','version',v_version,'sourceSnapshotHash',p.source_snapshot_hash,'checkSnapshotHash',p.check_snapshot_hash,'lockedAtUtc',p.locked_at_utc,'reasonCode',p_reason_code,'noteHash',p_note_hash,'idempotencyKey',p_idempotency_key,'intentHash',p_intent_hash);v_payload_hash:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(v_payload::text,'UTF8'),'sha256'),'hex');insert into finance.outbox_messages(legal_entity_id,topic,event_type,aggregate_type,aggregate_id,aggregate_version,payload,payload_hash,status,correlation_id) values(p.legal_entity_id,'finance.period','FINANCE_PERIOD_REOPENED','finance_period',p.id,v_version,v_payload,v_payload_hash,'PENDING',p_correlation_id);perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('audit:'||p.legal_entity_id::text,0));select ae.integrity_hash into v_previous from finance.audit_events ae where ae.legal_entity_id=p.legal_entity_id order by ae.created_at_utc desc,ae.id desc limit 1;v_audit:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(coalesce(v_previous,'GENESIS')||':'||p.id::text||':FINANCE_PERIOD_REOPENED:'||v_payload_hash||':'||p_correlation_id::text,'UTF8'),'sha256'),'hex');insert into finance.audit_events(legal_entity_id,actor_id,actor_type,action_code,subject_type,subject_id,decision,after_hash,previous_integrity_hash,integrity_hash,safe_context,correlation_id) values(p.legal_entity_id,p_actor_id,'USER','FINANCE_PERIOD_REOPENED','finance_period',p.id,'ALLOW',v_payload_hash,v_previous,v_audit,pg_catalog.jsonb_build_object('requestId',a.id,'reasonCode',p_reason_code,'noteHash',p_note_hash),p_correlation_id);return v_payload||pg_catalog.jsonb_build_object('outcome','REOPENED','periodStart',p.period_start,'periodEnd',p.period_end);end$$;
revoke all on function finance_api.authorize_period_reopen_request(uuid,text) from public,anon;revoke all on function finance_api.authorize_period_reopen_approval(uuid,text) from public,anon;revoke all on function finance_api.commit_period_reopen_request(uuid,uuid,uuid,uuid,uuid,text,text,uuid[],bigint,text,text,uuid) from public,anon,authenticated;revoke all on function finance_api.commit_period_reopen_approval(uuid,uuid,uuid,uuid,uuid,text,text,bigint,text,text,uuid) from public,anon,authenticated;
